import {createHash} from 'node:crypto';
import {utf} from '../protocol/primitives.js';
export function token(password:string,seed:Buffer,plugin:string):Buffer{if(!password)return Buffer.alloc(0);const pw=utf(password);const sha=(name,b)=>createHash(name).update(b).digest();if(plugin==='caching_sha2_password'){const a=sha('sha256',pw),b=sha('sha256',a),c=sha('sha256',Buffer.concat([b,seed]));return Buffer.from(a.map((v,i)=>v^c[i]));}if(plugin==='mysql_native_password'){const a=sha('sha1',pw),b=sha('sha1',a),c=sha('sha1',Buffer.concat([seed,b]));return Buffer.from(a.map((v,i)=>v^c[i]));}throw Error('Unsupported MySQL authentication plugin');}
